import React, { useState, useEffect } from "react";
import {
  Container,
  Row,
  Col,
  Card,
  Table,
  Button,
  Form,
  InputGroup,
  Badge,
} from "react-bootstrap";
import axios from "axios";

const SummaryCard = ({ title, value, subtitle, bg, icon }) => (
  <Card
    className="text-white mb-3 shadow-sm"
    style={{ background: bg, border: "none" }}
  >
    <Card.Body className="d-flex align-items-center">
      <div style={{ fontSize: 28, lineHeight: 1 }} className="me-3">
        {icon}
      </div>
      <div className="flex-grow-1">
        <div className="small text-uppercase opacity-75">{title}</div>
        <div className="h4 mb-1 fw-bold">{value}</div>
        <div className="small opacity-75">{subtitle}</div>
      </div>
    </Card.Body>
  </Card>
);

const Sidebar = ({ active, setActive }) => (
  <div
    className="sidebar p-3 d-flex flex-column"
    style={{
      minHeight: "85vh",
      background: "#f8fafc",
      borderRight: "1px solid rgba(0,0,0,0.04)",
    }}
  >
    <div className="mb-4 d-flex align-items-center">
      <div
        style={{
          width: 44,
          height: 44,
          borderRadius: 8,
          background: "#6f42c1",
        }}
        className="me-2"
      />
      <div>
        <div className="fw-bold">EDUCORE</div>
        <div className="small text-muted">Lecturer</div>
      </div>
    </div>

    <div className="d-flex flex-column" role="menu">
      <Button
        variant={active === "dashboard" ? "primary" : "link"}
        className="text-start mb-1"
        onClick={() => setActive("dashboard")}
      >
        🏠 Dashboard
      </Button>
      <Button
        variant={active === "courses" ? "primary" : "link"}
        className="text-start mb-1"
        onClick={() => setActive("courses")}
      >
        📚 Courses
      </Button>
      <Button
        variant={active === "modules" ? "primary" : "link"}
        className="text-start mb-1"
        onClick={() => setActive("modules")}
      >
        📦 Modules
      </Button>
      <Button
        variant={active === "tasks" ? "primary" : "link"}
        className="text-start mb-1"
        onClick={() => setActive("tasks")}
      >
        📝 Tasks
      </Button>
    </div>

    <div className="mt-auto">
      <hr />
      <Button
        variant="outline-danger"
        size="sm"
        className="w-100"
        onClick={() => {
          localStorage.clear();
          sessionStorage.clear();
          window.location.reload();
        }}
      >
        Logout
      </Button>
    </div>
  </div>
);

const LECTURER = () => {
  const [active, setActive] = useState("dashboard");
  const [courses, setCourses] = useState([]);
  const [modules, setModules] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [search, setSearch] = useState("");

  // Form states
  const [taskName, setTaskName] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [selectedModule, setSelectedModule] = useState("");

  useEffect(() => {
    fetchAssignedData();
    fetchTasks();
    // eslint-disable-next-line
  }, []);

  const fetchAssignedData = () => {
    axios
      .get("https://localhost:7013/api/Lecturer/Assigned/1") // replace lecturerId as needed
      .then((res) => {
        setCourses(res.data.courses || []);
        setModules(res.data.modules || []);
      })
      .catch((err) => console.error(err));
  };

  const fetchTasks = () => {
    axios
      .get("https://localhost:7013/api/Task/Lecturer/1") // replace lecturerId as needed
      .then((res) => {
        setTasks(res.data || []);
      })
      .catch((err) => console.error(err));
  };

  const handleAddTask = () => {
    if (!taskName || !dueDate || !selectedModule) {
      alert("Please complete all fields");
      return;
    }

    axios
      .post("https://localhost:7013/api/Task", {
        taskName,
        dueDate,
        moduleId: selectedModule,
        lecturerId: 1, // replace with real lecturerId
      })
      .then(() => {
        fetchTasks();
        setTaskName("");
        setDueDate("");
        setSelectedModule("");
      })
      .catch((err) => console.error(err));
  };

  // Derived counts for metrics
  const totalCourses = courses.length;
  const totalModules = modules.length;
  const totalTasks = tasks.length;

  // page-level inline style to match admin colours/layout
  const pageStyle = `
    .app-topbar { background: #fff; border-bottom: 1px solid rgba(0,0,0,0.05); }
    .search-input { min-width: 360px; }
  `;

  return (
    <>
      <style>{pageStyle}</style>
      <Container fluid className="p-0">
        {/* Topbar */}
        <div className="app-topbar p-2 d-flex align-items-center justify-content-between px-3">
          <div className="d-flex align-items-center gap-3">
            <Button
              variant="link"
              className="p-0"
              style={{ fontSize: 20, color: "#6f42c1" }}
            >
              ☰
            </Button>
            <div className="d-flex align-items-center">
              <div
                style={{
                  width: 40,
                  height: 40,
                  borderRadius: 8,
                  background: "#6f42c1",
                }}
              />
              <div
                className="ms-2 fw-bold"
                style={{ color: "#6f42c1" }}
              >
                Educore
              </div>
            </div>
          </div>

          <div className="d-flex align-items-center">
            <InputGroup className="me-3 search-input">
              <Form.Control
                placeholder="Search tasks, modules..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              <Button
                variant="primary"
                onClick={() => {
                  /* keep search local */
                }}
              >
                Search
              </Button>
            </InputGroup>

            <div className="d-flex align-items-center gap-3">
              <div style={{ fontSize: 18, color: "#6c757d" }}>🌙</div>
              <div style={{ fontSize: 18, color: "#6c757d" }}>🔔</div>
              <div
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: "50%",
                  background: "#dee2e6",
                }}
              />
            </div>
          </div>
        </div>

        <Row className="g-0">
          <Col lg={2} className="pe-0">
            <Sidebar active={active} setActive={setActive} />
          </Col>

          <Col lg={10} className="p-4">
            {/* Metrics */}
            <Row className="mb-3">
              <Col md={3}>
                <SummaryCard
                  title="Courses"
                  value={totalCourses}
                  subtitle="Active courses"
                  bg="linear-gradient(90deg, #5b8def, #4aa0ff)"
                  icon="📚"
                />
              </Col>
              <Col md={3}>
                <SummaryCard
                  title="Modules"
                  value={totalModules}
                  subtitle="Assigned modules"
                  bg="linear-gradient(90deg, #7b5cf6, #6f42c1)"
                  icon="📦"
                />
              </Col>
              <Col md={3}>
                <SummaryCard
                  title="Tasks"
                  value={totalTasks}
                  subtitle="Pending & upcoming"
                  bg="linear-gradient(90deg, #ffb249, #ff9a2c)"
                  icon="📝"
                />
              </Col>
              <Col md={3}>
                <SummaryCard
                  title="Due Soon"
                  value={tasks.filter((t) => {
                    if (!t.dueDate) return false;
                    const d = new Date(t.dueDate);
                    const diff = (d - new Date()) / (1000 * 60 * 60 * 24);
                    return diff <= 7 && diff >= 0;
                  }).length}
                  subtitle="Next 7 days"
                  bg="linear-gradient(90deg, #ff5f6d, #ffc371)"
                  icon="⏳"
                />
              </Col>
            </Row>

            {/* Main content */}
            <Card className="shadow-sm mb-3">
              <Card.Body>
                <div className="d-flex justify-content-between align-items-center mb-3">
                  <div>
                    <h5 className="mb-0">Lecturer Dashboard</h5>
                    <div className="text-muted small">
                      Manage your courses, modules and tasks
                    </div>
                  </div>

                  <div>
                    <Badge bg="secondary" className="me-2">
                      Role: Lecturer
                    </Badge>
                    <Button
                      variant="outline-secondary"
                      size="sm"
                      onClick={() => setActive("tasks")}
                    >
                      View Tasks
                    </Button>
                  </div>
                </div>

                {/* Courses & Modules summary */}
                {active === "dashboard" && (
                  <Row>
                    <Col md={6}>
                      <Card className="mb-3">
                        <Card.Header>
                          <strong>Your Courses</strong>
                        </Card.Header>
                        <Card.Body>
                          {courses.length > 0 ? (
                            <ul className="mb-0">
                              {courses.map((c, i) => <li key={i}>{c.name}</li>)}
                            </ul>
                          ) : (
                            <div className="text-muted">No courses assigned</div>
                          )}
                        </Card.Body>
                      </Card>
                    </Col>

                    <Col md={6}>
                      <Card className="mb-3">
                        <Card.Header>
                          <strong>Your Modules</strong>
                        </Card.Header>
                        <Card.Body>
                          {modules.length > 0 ? (
                            <ul className="mb-0">
                              {modules.map((m, i) => <li key={i}>{m.name}</li>)}
                            </ul>
                          ) : (
                            <div className="text-muted">No modules assigned</div>
                          )}
                        </Card.Body>
                      </Card>
                    </Col>
                  </Row>
                )}

                {/* Courses view */}
                {active === "courses" && (
                  <div>
                    <h6>Courses</h6>
                    <Table striped bordered hover responsive>
                      <thead>
                        <tr>
                          <th>#</th>
                          <th>Name</th>
                          <th>Code</th>
                        </tr>
                      </thead>
                      <tbody>
                        {courses.length > 0 ? (
                          courses.map((c, i) => (
                            <tr key={i}>
                              <td>{i + 1}</td>
                              <td>{c.name}</td>
                              <td>{c.code || "—"}</td>
                            </tr>
                          ))
                        ) : (
                          <tr>
                            <td colSpan="3" className="text-center text-muted">
                              No courses assigned
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </Table>
                  </div>
                )}

                {/* Modules view */}
                {active === "modules" && (
                  <div>
                    <h6>Modules</h6>
                    <Table striped bordered hover responsive>
                      <thead>
                        <tr>
                          <th>#</th>
                          <th>Name</th>
                          <th>Code</th>
                        </tr>
                      </thead>
                      <tbody>
                        {modules.length > 0 ? (
                          modules.map((m, i) => (
                            <tr key={i}>
                              <td>{i + 1}</td>
                              <td>{m.name}</td>
                              <td>{m.code || "—"}</td>
                            </tr>
                          ))
                        ) : (
                          <tr>
                            <td colSpan="3" className="text-center text-muted">
                              No modules assigned
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </Table>
                  </div>
                )}

                {/* Tasks view (default to tasks when active) */}
                {active === "tasks" && (
                  <>
                    <div className="mb-3 d-flex gap-2">
                      <InputGroup style={{ maxWidth: 520 }}>
                        <Form.Control
                          placeholder="Filter tasks by name"
                          value={search}
                          onChange={(e) => setSearch(e.target.value)}
                        />
                        <Button
                          variant="primary"
                          onClick={() => {
                            /* kept for UI parity */
                          }}
                        >
                          Search
                        </Button>
                      </InputGroup>

                      <div className="ms-auto d-flex gap-2">
                        <Button
                          onClick={() => {
                            setTaskName("");
                            setDueDate("");
                            setSelectedModule("");
                            setActive("tasks");
                          }}
                        >
                          New Task
                        </Button>
                      </div>
                    </div>

                    <Card className="mb-3">
                      <Card.Header>
                        <strong>Create Task</strong>
                      </Card.Header>
                      <Card.Body>
                        <Form>
                          <Row className="g-2">
                            <Col md={5}>
                              <Form.Control
                                type="text"
                                placeholder="Task name"
                                value={taskName}
                                onChange={(e) => setTaskName(e.target.value)}
                              />
                            </Col>
                            <Col md={3}>
                              <Form.Control
                                type="date"
                                value={dueDate}
                                onChange={(e) => setDueDate(e.target.value)}
                              />
                            </Col>
                            <Col md={3}>
                              <Form.Select
                                value={selectedModule}
                                onChange={(e) => setSelectedModule(e.target.value)}
                              >
                                <option value="">Select module</option>
                                {modules.map((m, i) => (
                                  <option key={i} value={m.moduleId}>
                                    {m.name}
                                  </option>
                                ))}
                              </Form.Select>
                            </Col>
                            <Col md={1}>
                              <Button onClick={handleAddTask}>Add</Button>
                            </Col>
                          </Row>
                        </Form>
                      </Card.Body>
                    </Card>

                    <Card>
                      <Card.Header>
                        <strong>Tasks</strong>
                      </Card.Header>
                      <Card.Body>
                        <Table striped bordered hover responsive>
                          <thead>
                            <tr>
                              <th>#</th>
                              <th>Task</th>
                              <th>Due</th>
                              <th>Module</th>
                            </tr>
                          </thead>
                          <tbody>
                            {tasks &&
                            tasks.filter((t) =>
                              search
                                ? (t.taskName || "")
                                    .toLowerCase()
                                    .includes(search.toLowerCase())
                                : true
                            ).length > 0 ? (
                              tasks
                                .filter((t) =>
                                  search
                                    ? (t.taskName || "")
                                        .toLowerCase()
                                        .includes(search.toLowerCase())
                                    : true
                                )
                                .map((t, i) => (
                                  <tr key={i}>
                                    <td>{t.taskId || i + 1}</td>
                                    <td>{t.taskName}</td>
                                    <td>
                                      {t.dueDate
                                        ? new Date(t.dueDate).toLocaleDateString()
                                        : "—"}
                                    </td>
                                    <td>
                                      {t.moduleName ||
                                        modules.find(
                                          (m) => m.moduleId === t.moduleId
                                        )?.name ||
                                        "—"}
                                    </td>
                                  </tr>
                                ))
                            ) : (
                              <tr>
                                <td colSpan="4" className="text-center text-muted">
                                  No tasks created
                                </td>
                              </tr>
                            )}
                          </tbody>
                        </Table>
                      </Card.Body>
                    </Card>
                  </>
                )}
              </Card.Body>
            </Card>

            <Row>
              <Col md={6}>
                <Card className="shadow-sm">
                  <Card.Body>
                    <h6 className="mb-2">Quick Actions</h6>
                    <div className="d-flex justify-content-between">
                      <div>Courses</div>
                      <Badge bg="info">{totalCourses}</Badge>
                    </div>
                    <div className="d-flex justify-content-between mt-2">
                      <div>Modules</div>
                      <Badge bg="info">{totalModules}</Badge>
                    </div>
                    <div className="d-flex gap-2 mt-3">
                      <Button
                        variant="outline-primary"
                        onClick={() => setActive("courses")}
                      >
                        Go to Courses
                      </Button>
                      <Button
                        variant="outline-secondary"
                        onClick={() => setActive("modules")}
                      >
                        Go to Modules
                      </Button>
                    </div>
                  </Card.Body>
                </Card>
              </Col>

              <Col md={6}>
                <Card className="shadow-sm">
                  <Card.Body>
                    <h6 className="mb-2">Reports</h6>
                    <div className="small text-muted">
                      Recent activity and quick stats will appear here.
                    </div>
                  </Card.Body>
                </Card>
              </Col>
            </Row>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default LECTURER;
